function solve(n, m) {
  const f = (k) => {
    if (k === 0) return [0, 1];
    const [a, b] = f(Math.floor(k / 2));
    const c = (a * (2 * b - a + m)) % m;
    const d = (a * a + b * b) % m;
    return k % 2 === 0 ? [c, d] : [d, (c + d) % m];
  };
  return f(n)[0];
}
